Bell state with PennyLane.
"""
import pennylane as qml


def main():
    dev = qml.device("default.qubit", wires=2, shots=100)
    @qml.qnode(dev)
    def bell():
        qml.Hadamard(wires=0)
        qml.CNOT(wires=[0, 1])
