"""
QFT on 3 qubits with PennyLane.
"""
import pennylane as qml
import numpy as np


def main():
    dev = qml.device("default.qubit", wires=3)
    @qml.qnode(dev)
    def qft_circuit():
        # Prepare |001>
        qml.PauliX(wires=0)
        # QFT
        for i in range(3):
            qml.Hadamard(wires=i)
            for j in range(i + 1, 3):
                qml.ctrl(qml.PhaseShift, control=j)(np.pi / (2 ** (j - i)), wires=i)
        return qml.state()
    state = qft_circuit()
    print(f"PennyLane QFT |001> first 4 amplitudes: {state[:4]}")


if __name__ == "__main__":
    main()

"""
PennyLane QAOA MaxCut on a triangle.
"""
import pennylane as qml
from pennylane import numpy as np


def main():
    n = 3
    edges = [(0, 1), (1, 2), (0, 2)]
    dev = qml.device("default.qubit", wires=n)

    def cost_hamiltonian():
        coeffs = [1.0] * len(edges)
        obs = [qml.PauliZ(i) @ qml.PauliZ(j) for i, j in edges]
        return qml.Hamiltonian(coeffs, obs)

    def mixer_hamiltonian():
        return qml.Hamiltonian([-1.0] * n, [qml.PauliX(i) for i in range(n)])

    H_c = cost_hamiltonian()
    H_m = mixer_hamiltonian()

    @qml.qnode(dev)
    def circuit(gamma, beta):
        for w in range(n):
            qml.Hadamard(wires=w)
        for _ in range(1):
            qml.exp(H_c, 1j * gamma)
            qml.exp(H_m, 1j * beta)
        return qml.expval(H_c)

    np.random.seed(42)
    gamma = np.array(0.5, requires_grad=True)
    beta = np.array(0.5, requires_grad=True)
    opt = qml.optimize.AdamOptimizer(stepsize=0.05)

    def cost(params):
        return circuit(params[0], params[1])

    params = np.array([gamma, beta], requires_grad=True)
    for _ in range(150):
        params = opt.step(cost, params)

    energy = float(cost(params))
    print(f"PennyLane QAOA energy: {energy:.4f} (max-cut {int(-energy)})")


if __name__ == "__main__":
    main()

"""
PennyLane QFT and inverse QFT round-trip.
"""
import pennylane as qml
import numpy as np


def main():
    dev = qml.device("default.qubit", wires=3)
    @qml.qnode(dev)
    def round_trip():
        # Prepare |010>
        qml.PauliX(wires=1)
        # QFT
        for i in range(3):
            qml.Hadamard(wires=i)
            for j in range(i + 1, 3):
                qml.ctrl(qml.PhaseShift, control=j)(np.pi / (2 ** (j - i)), wires=i)
        # Inverse QFT
        for i in range(2, -1, -1):
            for j in range(2, i, -1):
                qml.ctrl(qml.PhaseShift, control=j)(-np.pi / (2 ** (j - i)), wires=i)
            qml.Hadamard(wires=i)
        return qml.state()
    state = round_trip()
    # Should be |010> = [0,0,1,0,0,0,0,0]
    probs = np.abs(state) ** 2
    print(f"PennyLane QFT-iQFT prob[010]={probs[2]:.4f}")


if __name__ == "__main__":
    main()

"""
PennyLane quantum natural gradient on a simple cost.
