    main()

"""
Taylor series approximation of exp(x) and sin(x).
"""


def exp_taylor(x, terms=15):
    result = 0
    factorial = 1
    for n in range(terms):
        if n > 0:
            factorial *= n
        result += x ** n / factorial
    return result


def sin_taylor(x, terms=15):
    result = 0
    factorial = 1
    for n in range(terms):
        if n > 0:
            factorial *= n
        sign = (-1) ** (n // 2)
        if n % 2 == 1:
            result += sign * x ** n / factorial
    return result


def main():
    e1 = exp_taylor(1.0)
    s1 = sin_taylor(1.0)
    import math
    print(f"Taylor exp(1)={e1:.6f} (exact {math.exp(1):.6f})")
    print(f"Taylor sin(1)={s1:.6f} (exact {math.sin(1):.6f})")


if __name__ == "__main__":
    main()

"""
Simple in-memory SQL-like join: join two lists of dicts on a key.
"""


def join(left, right, left_key, right_key):
    """Hash join of two lists of dicts."""
    index = {}
    for r in right:
        index.setdefault(r[right_key], []).append(r)
    result = []
    for l in left:
        for r in index.get(l[left_key], []):
            merged = {**l, **r}
            result.append(merged)
    return result


def main():
    users = [
        {"user_id": 1, "name": "Alice"},
        {"user_id": 2, "name": "Bob"},
        {"user_id": 3, "name": "Charlie"},
    ]
    orders = [
        {"order_id": 100, "user_id": 1, "amount": 50},
        {"order_id": 101, "user_id": 1, "amount": 30},
        {"order_id": 102, "user_id": 2, "amount": 20},
    ]
    result = join(users, orders, "user_id", "user_id")
    print(f"SQL join result count: {len(result)}")


