"""
Sieve of Eratosthenes.
"""


def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]


def main():
    primes = sieve(30)
    print(f"Primes up to 30: {primes}")


if __name__ == "__main__":
    main()

"""
Run-length encoding compression.
"""


def rle_encode(s):
    if not s:
        return ""
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(s[i - 1] + str(count))
            count = 1
    result.append(s[-1] + str(count))
    return "".join(result)


def rle_decode(s):
    result = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        num = ""
        while i < len(s) and s[i].isdigit():
            num += s[i]
            i += 1
        result.append(char * int(num))
    return "".join(result)


def main():
    text = "AAAABBBCCDAA"
    encoded = rle_encode(text)
    decoded = rle_decode(encoded)
    print(f"RLE: {text} -> {encoded} -> {decoded} (round-trip ok={text==decoded})")


if __name__ == "__main__":
    main()
